import https from 'node:https';
import tls from 'node:tls';
import fs from 'node:fs';

// ── 1. Inspect TLS connection details programmatically ────────
function inspectTLS(hostname, port = 443) {
  return new Promise((resolve, reject) => {
    const socket = tls.connect({ host: hostname, port, servername: hostname }, () => {
      const cert = socket.getPeerCertificate(true);
      const protocol = socket.getProtocol();
      const cipher = socket.getCipher();

      resolve({
        protocol,                                    // e.g., 'TLSv1.3'
        cipher: cipher.name,                         // e.g., 'TLS_AES_256_GCM_SHA384'
        subject: cert.subject?.CN,                   // e.g., 'example.com'
        issuer: cert.issuer?.O,                      // e.g., 'Let's Encrypt'
        validFrom: cert.valid_from,
        validTo: cert.valid_to,
        fingerprint: cert.fingerprint256,
        subjectAltNames: cert.subjectaltname,         // SAN list
      });
      socket.destroy();
    });
    socket.on('error', reject);
  });
}

// ── 2. HTTPS server with secure TLS configuration ────────────
function createSecureServer(certPath, keyPath) {
  const options = {
    cert: fs.readFileSync(certPath),
    key:  fs.readFileSync(keyPath),
    minVersion: 'TLSv1.2',             // Reject TLS 1.0 and 1.1
    ciphers: [
      'TLS_AES_256_GCM_SHA384',        // TLS 1.3 (automatic if minVersion allows)
      'TLS_CHACHA20_POLY1305_SHA256',
      'ECDHE-ECDSA-AES256-GCM-SHA384', // TLS 1.2 with forward secrecy
      'ECDHE-RSA-AES256-GCM-SHA384',
    ].join(':'),
    honorCipherOrder: true,             // Server picks cipher, not client
  };

  const server = https.createServer(options, (req, res) => {
    // Security headers every HTTPS response should include
    res.setHeader('Strict-Transport-Security', 'max-age=63072000; includeSubDomains; preload');
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-Frame-Options', 'DENY');
    res.setHeader('Content-Security-Policy', "default-src 'self'");
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'secure' }));
  });

  return server;
}

// ── 3. Certificate expiry monitoring ─────────────────────────
async function checkCertExpiry(hostname) {
  const info = await inspectTLS(hostname);
  const expiresAt = new Date(info.validTo);
  const daysLeft = Math.floor((expiresAt - Date.now()) / (86400 * 1000));
  console.log(`${hostname}: expires in ${daysLeft} days (${info.validTo})`);
  if (daysLeft < 30) console.warn('WARNING: Certificate expiring soon!');
  return daysLeft;
}

